frappe.ui.form.on("HD Ticket", {
    before_workflow_action: function (frm) {

        let action = frm.selected_workflow_action;
        let missing_fields = [];

        // Start Work Validation
        if (action === "Start Work") {

            if (!frm.doc.custom_assigned_to) {
                missing_fields.push("Assigned To");
                frm.scroll_to_field("custom_assigned_to");
            }

        }

        // Resolve Validation
        if (action === "Resolve") {

            if (!frm.doc.custom_resolution_code) {
                missing_fields.push("Resolution Code");
            }

            if (!frm.doc.custom_solution) {
                missing_fields.push("Solution");
            }

            if (missing_fields.length > 0) {
                frm.scroll_to_field("custom_resolution_code");
            }

        }

        // Close Ticket Validation
        if (action === "Close Ticket") {

            if (!frm.doc.custom_closure_code) {
                missing_fields.push("Closure Code");
            }

            if (!frm.doc.custom_closure_category) {
                missing_fields.push("Closure Category");
            }

            if (missing_fields.length > 0) {
                frm.scroll_to_field("custom_closure_code");
            }

        }

        // Cancel Validation
        if (action === "Cancle") {

            if (!frm.doc.custom_cancellation_remarks) {
                missing_fields.push("Cancellation Remarks");
                frm.scroll_to_field("custom_cancellation_remarks");
            }

        }

        // Put on Hold Validation
        if (action === "Put on Hold") {

            if (!frm.doc.custom_pending_reason) {
                missing_fields.push("Pending Reason");
                frm.scroll_to_field("custom_pending_reason");
            }

        }

        // Show combined error
        if (missing_fields.length > 0) {

            frappe.msgprint({
                title: "Mandatory Fields Missing",
                message:
                    "Please fill the following fields before performing this action:<br><br><b>" +
                    missing_fields.join("<br>") +
                    "</b>",
                indicator: "red"
            });

            frappe.dom.unfreeze();
            throw "Stop Workflow";
        }

    }
});

frappe.ui.form.on('HD Ticket', {
    validate: function(frm) {
        if (frm.doc.custom_solution && frm.doc.custom_solution.length < 20) {
            frappe.throw("First Name must be at least 20 characters long.");
        }
    }
});

frappe.ui.form.on('HD Ticket', {
    refresh: function(frm) {
        handle_sla_calculations(frm);
    },
    onload: function(frm) {
        handle_sla_calculations(frm);
    }
});

function handle_sla_calculations(frm) {
    let now = frappe.datetime.now_datetime();
    let has_silently_updated = false;
    let has_breached = false;

    // 1. Response SLA Breach Logic
    if (frm.doc.response_by && now > frm.doc.response_by) {
        if (frm.doc.custom_response_sla_breach !== "YES" && !["Resolved", "Closed"].includes(frm.doc.status)) {
            frm.set_value('custom_response_sla_breach', 'YES');
            has_breached = true;
        }
    } else if (!frm.doc.custom_response_sla_breach) {
        // Silent assignment
        frm.doc.custom_response_sla_breach = "NO";
        has_silently_updated = true;
    }

    // 2. Resolution SLA Breach Logic
    if (frm.doc.resolution_by && now > frm.doc.resolution_by) {
        if (frm.doc.custom_resolution_sla_breach !== "YES" && !["Resolved", "Closed"].includes(frm.doc.status)) {
            frm.set_value('custom_resolution_sla_breach', 'YES');
            has_breached = true;
        }
    } else if (!frm.doc.custom_resolution_sla_breach) {
        // Silent assignment
        frm.doc.custom_resolution_sla_breach = "NO";
        has_silently_updated = true;
    }

    // Handle UI refreshing without showing "Not Saved"
    if (has_breached) {
        // If it's a breach, we WANT it to show Not Saved so the user saves the 'YES'
        frm.refresh_field('custom_response_sla_breach');
        frm.refresh_field('custom_resolution_sla_breach');
    } else if (has_silently_updated) {
        // If we just set "NO" as a default, we force refresh but KILL the "Not Saved" flag
        frm.refresh_field('custom_response_sla_breach');
        frm.refresh_field('custom_resolution_sla_breach');

        // This is the magic line that removes "Not Saved"
        frm.dirty(); // Clears any existing dirty state
        $(frm.wrapper).find('.indicator-pill.orange').remove(); // UI cleanup
    }
}

frappe.ui.form.on('HD Ticket', {
    refresh: function(frm) {
        // Runs when the ticket is opened
        if (frm.doc.subject && !frm.doc.custom_priorityy) {
            parse_emea_subject(frm);
        }
    },
    subject: function(frm) {
        // Runs if the subject is changed manually
        parse_emea_subject(frm);
    }
});

function parse_emea_subject(frm) {
    if (frm.doc.subject) {
        let subject = frm.doc.subject.toLowerCase();
        let is_emea_ticket = false;

        // Priority and Impact Mapping
        if (subject.includes("critical")) {
            frm.set_value('custom_priorityy', 'P1');
            frm.set_value('priority', 'Critical');
            frm.set_value('custom_impact', 'S1'); // Fixed from '1' to 'S1'
            is_emea_ticket = true;
        } 
        else if (subject.includes("high")) {
            frm.set_value('custom_priorityy', 'P2');
            frm.set_value('priority', 'High');
            frm.set_value('custom_impact', 'S2');
            is_emea_ticket = true;
        } 
        else if (subject.includes("medium")) {
            frm.set_value('custom_priorityy', 'P3');
            frm.set_value('priority', 'Medium');
            frm.set_value('custom_impact', 'S3');
            is_emea_ticket = true;
        }
        else if (subject.includes("low")) {
            frm.set_value('custom_priorityy', 'P4');
            frm.set_value('priority', 'Low');
            frm.set_value('custom_impact', 'S4');
            is_emea_ticket = true;
        }

        // Setting the Workgroup (Department Link Field)
        if (is_emea_ticket) {
            // This sets the new custom_workgroup field to "EMEA Support Group"
            // Ensure "EMEA Support Group" exists in your Department list
            frm.set_value('custom_workgroup', 'EMEA Support Group');
        }
    }
}

