frappe.ui.form.on('HD Ticket', {
    refresh: function(frm) {
        frm._old_status = frm.doc.status;
    },

    status: function(frm) {
        if (
            frm._old_status === "Open" &&
            frm.doc.status === "In Progress" &&
            !frm.doc.first_responded_on
        ) {
            frm.set_value("first_responded_on", frappe.datetime.now_datetime());
        }

        frm._old_status = frm.doc.status;
    }
});

frappe.ui.form.on("HD Ticket", {
    refresh(frm) {
        const show = frm.doc.status === "In-Progress";
        frm.toggle_display("custom_resolution_code", show);
    }
});

frappe.ui.form.on('HD Ticket', {
    before_workflow_action: (frm) => {
        // This function intercepts the workflow button click
        return new Promise((resolve, reject) => {
            frappe.confirm(
                `Are you sure you want to proceed with the action: <b>${frm.selected_workflow_action}</b>?`,
                () => {
                    // If user clicks 'Yes'
                    resolve();
                },
                () => {
                    // If user clicks 'No'
                    reject();
                }
            );
        });
    }
});

frappe.ui.form.on('HD Ticket', {
    before_workflow_action: function(frm) {
        // 1. Check if we already confirmed this specific action
        if (frm.is_confirmed === frm.selected_workflow_action) {
            // Reset the flag for next time and let the workflow proceed
            frm.is_confirmed = null;
            return Promise.resolve();
        }

        // 2. If not confirmed, stop the workflow and show the box
        return new Promise((resolve, reject) => {
            // Force unfreeze so the UI is clickable
            frappe.dom.unfreeze();

            frappe.confirm(
                __(`Are you sure you want to proceed with: <b>${frm.selected_workflow_action}</b>?`),
                () => {
                    // 3. Set the flag so the second trigger knows we said 'Yes'
                    frm.is_confirmed = frm.selected_workflow_action;
                    resolve();
                },
                () => {
                    // 4. User said 'No', clear everything
                    frm.is_confirmed = null;
                    frappe.dom.unfreeze();
                    reject();
                }
            );
        });
    }
});

frappe.ui.form.on("HD Ticket", {

    refresh: function(frm) {
        auto_move_in_progress(frm);
    },

    after_save: function(frm) {
        auto_move_in_progress(frm);
    }
});

function auto_move_in_progress(frm) {

    if (!frm.doc._assign) return;

    let assigned_users = JSON.parse(frm.doc._assign || "[]");

    if (assigned_users.length > 0 && frm.doc.status === "New") {
        frm.set_value("status", "In-Progress");
        frm.save();
    }
}

frappe.ui.form.on('HD Ticket', {

    refresh: function(frm) {
        apply_workgroup_filter(frm);
    },

    custom_workgroup: function(frm) {
        apply_workgroup_filter(frm);
    }
});

function apply_workgroup_filter(frm) {

    if (!frm.doc.custom_workgroup) return;

    frappe.call({
        method: "frappe.client.get",
        args: {
            doctype: "HD Team",
            name: frm.doc.custom_workgroup
        },
        callback: function(r) {

            if (!r.message) return;

            let users = [];

            (r.message.users || []).forEach(function(row) {
                if (row.user) {
                    users.push(row.user);
                }
            });

            console.log("Workgroup Users:", users);

            frm.set_query("custom_assigned_to", function() {
                return {
                    filters: {
                        name: ["in", users]
                    }
                };
            });

            frm.refresh_field("custom_assigned_to");

            if (users.length > 0) {
                frm.set_value("custom_assigned_to", users[0]);
            }
        }
    });
}

frappe.ui.form.on('HD Ticket', {
    etr: function(frm) {
        let row = frm.add_child('custom_etr_history');
        row.etr = frm.doc.etr;
        row.etr_justification = frm.doc.etr_justification;
        row.changed_date = frappe.datetime.now_datetime();
        row.changed_by = frappe.session.user;

        frm.refresh_field('custom_etr_history');
    }
});

frappe.ui.form.on('HD Ticket', {
    validate(frm) {
        if (frm.is_new() && !frm.doc.custom_logged_time) {
            frm.set_value('custom_logged_time', frappe.datetime.now_datetime());
        }
    }
});

frappe.ui.form.on('HD Ticket', {

    refresh: function(frm) {

        // store original values
        frm.initial_priority = frm.doc.priority;
        frm.initial_impact = frm.doc.custom_impact;
        frm.initial_priorityy = frm.doc.custom_priorityy;

        // hide reason field
        if (!frm.doc.custom_reason_for_change) {
            frm.set_df_property('custom_reason_for_change', 'hidden', 1);
        }
    },

    priority: function(frm) {
        check_change(frm);
    },

    custom_impact: function(frm) {
        check_change(frm);
    },

    custom_priorityy: function(frm) {
        check_change(frm);
    },

    validate: function(frm) {

        if (frm.is_new()) return;

        let changed =
            frm.doc.priority !== frm.initial_priority ||
            frm.doc.custom_impact !== frm.initial_impact ||
            frm.doc.custom_priorityy !== frm.initial_priorityy;

        if (changed && !frm.doc.custom_reason_for_change) {
            frappe.throw("Please enter Reason for Change before updating Urgency / Impact / Priority");
        }

    }

});


function check_change(frm) {

    if (frm.is_new()) return;

    frm.set_df_property('custom_reason_for_change', 'hidden', 0);
    frm.set_df_property('custom_reason_for_change', 'reqd', 1);

}
